<?php
$days=array_keys($current['daily']);$count=count($days);$width=max(800,$count*32+75);$chartHeight=250;$baseX=65;$plotWidth=$width-80;$plotHeight=195;
$values=[];foreach($current['daily'] as $day){$values[]=$day[$mode]['revenue'];$values[]=$day[$mode]['gross_profit'];}
$values=array_values(array_filter($values,static fn($v)=>$v!==null));$values=$values?:[0];$max=max(1,max($values));$min=min(0,min($values));$range=$max-$min;$y=static fn($value)=>15+($max-$value)/$range*$plotHeight;$zero=$y(0);$step=$plotWidth/max(1,$count);
?>
<div class="overflow-x-auto"><svg viewBox="0 0 <?= $width ?> 250" style="min-width:<?= $width ?>px;width:100%;height:280px" role="img" aria-label="Grafik batang omzet dan laba harian">
<?php for($i=0;$i<=4;$i++):$tick=$min+$range*$i/4;$yy=$y($tick); ?><line x1="65" x2="<?= $width-15 ?>" y1="<?= $yy ?>" y2="<?= $yy ?>" stroke="#e2e8f0"/><text x="60" y="<?= $yy+4 ?>" text-anchor="end" fill="#94a3b8" font-size="9"><?= htmlspecialchars(abs($tick)>=1000000?number_format($tick/1000000,1,',','.').' jt':number_format($tick,0,',','.')) ?></text><?php endfor; ?>
<?php foreach($days as $i=>$date):$day=$current['daily'][$date][$mode];$x=$baseX+$i*$step;foreach(['revenue'=>'#20b486','gross_profit'=>'#7295f3'] as $key=>$color):if($day[$key]===null)continue;$barY=$y($day[$key]); ?><rect x="<?= $x+($key==='gross_profit'?$step*.42:0) ?>" y="<?= min($zero,$barY) ?>" width="<?= $step*.34 ?>" height="<?= max(0.5,abs($zero-$barY)) ?>" rx="2" fill="<?= $color ?>"><title><?= htmlspecialchars($date.' · '.($key==='revenue'?'Omzet':'Laba setelah HPP').': '.formatRp($day[$key])) ?></title></rect><?php endforeach; ?><text x="<?= $x+$step*.35 ?>" y="230" text-anchor="middle" fill="#94a3b8" font-size="8"><?= htmlspecialchars(substr($date,8,2).'/'.substr($date,5,2)) ?></text><?php endforeach; ?>
</svg></div>
<?php $maxOrders=max(1,max(array_map(static fn($day)=>$day[$mode]['orders'],$current['daily'])));$points=[];foreach($days as $i=>$date)$points[]=($baseX+$i*$step+$step*.35).','.round(125-$current['daily'][$date][$mode]['orders']/$maxOrders*100,2); ?>
<div class="overflow-x-auto"><svg viewBox="0 0 <?= $width ?> 160" style="min-width:<?= $width ?>px;width:100%;height:170px" role="img" aria-label="Grafik pesanan dan retur harian"><line x1="65" x2="<?= $width-15 ?>" y1="125" y2="125" stroke="#e2e8f0"/><polyline points="<?= implode(' ',$points) ?>" stroke="#6d4cce" stroke-width="2" fill="none"/><?php foreach($days as $i=>$date):$day=$current['daily'][$date][$mode];$x=$baseX+$i*$step+$step*.35;$yy=125-$day['orders']/$maxOrders*100;$returns=$current['daily'][$date]['all']['returns']; ?><circle cx="<?= $x ?>" cy="<?= $yy ?>" r="4" fill="#6d4cce"><title><?= htmlspecialchars($date.' · Pesanan: '.$day['orders'].' · Retur: '.$returns) ?></title></circle><rect x="<?= $x-4 ?>" y="<?= 125-$returns/$maxOrders*100 ?>" width="8" height="<?= max(.5,$returns/$maxOrders*100) ?>" fill="#fbbf24"/><text x="<?= $x ?>" y="150" text-anchor="middle" fill="#94a3b8" font-size="8"><?= htmlspecialchars(substr($date,8,2).'/'.substr($date,5,2)) ?></text><?php endforeach; ?><text x="5" y="25" fill="#94a3b8" font-size="9"><?= $maxOrders ?> pesanan</text></svg></div>
